using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps;using MapSharedProps.EditorTools;using MapTunnels.EditorTools;
public static class Cobweb190Views {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));public static string Out=Path.Combine(Root,"Evidence190");static string Input=>Path.Combine(Root,"Input177");public static string Folder="Assets/Imported177-valid";
 static void Check(bool b,string s){if(!b)throw new Exception(s);}static void Shot(Camera c,string n){FreezeLegacy();var t=Shared117Review.Image(c,1280,720);File.WriteAllBytes(Path.Combine(Out,n+".png"),t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}
 static void FreezeLegacy(){foreach(var c in UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsSortMode.None)){if(!c||!c.GetType().Name.EndsWith("Presentation"))continue;var method=c.GetType().GetMethod("ApplyPresentation",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);if(method!=null&&method.GetParameters().Length==1&&method.GetParameters()[0].ParameterType==typeof(float))method.Invoke(c,new object[]{1f});}}
 static Camera Cam(){var c=new GameObject("背景撮影").AddComponent<Camera>();c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.02f,.025f,.03f);c.fieldOfView=45;c.nearClipPlane=.03f;return c;}
 static GameObject Web(Vector3 p,Quaternion q,Transform parent=null){var o=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"/small-mine_cobweb.prefab"));o.transform.SetParent(parent,false);o.transform.SetPositionAndRotation(p,q);return o;}
 static void Empty(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.03f,.035f,.04f);}
 static GameObject Box(string name,Vector3 p,Vector3 s,Material m){var o=GameObject.CreatePrimitive(PrimitiveType.Cube);o.name=name;o.transform.position=p;o.transform.localScale=s;o.GetComponent<Renderer>().sharedMaterial=m;return o;}
 public static void Studio(){Empty();var wm=new Material(Shader.Find("Universal Render Pipeline/Lit")){color=new Color(.25f,.24f,.22f)};var wood=new Material(wm){color=new Color(.15f,.10f,.06f)};var wall=Box("壁",new Vector3(0,1.5f,.09f),new Vector3(3,3,.15f),wm);var beam=Box("梁",new Vector3(0,2.20f,-.015f),new Vector3(2.2f,.15f,.18f),wood);var post=Box("柱",new Vector3(-.73f,1.1f,-.015f),new Vector3(.15f,2.2f,.18f),wood);var w=Web(new Vector3(0,1.65f,0),Quaternion.identity);var light=new GameObject("局所光").AddComponent<Light>();light.type=LightType.Point;light.color=new Color(1,.78f,.52f);light.intensity=16;light.range=8;light.shadows=LightShadows.Soft;var c=Cam();var target=new Vector3(0,1.65f,-.10f);foreach(var view in new[]{"close","normal","far","opposite","back","dark","unlit","edge","move0","move1","move2"}){bool back=view=="back";wall.SetActive(!back);beam.SetActive(!back);post.SetActive(!back);light.transform.position=new Vector3(view=="opposite"?-1:1,2.2f,back?2:-2);light.intensity=view=="unlit"?0:view=="dark"?2:16;RenderSettings.ambientLight=view=="unlit"?Color.black:new Color(.03f,.035f,.04f);Vector3 offset=view=="normal"?new Vector3(0,8,-6):view=="far"?new Vector3(0,12.8f,-9.6f):back?new Vector3(0,.2f,3):view=="edge"?new Vector3(2.8f,.2f,-.5f):new Vector3(.3f,.2f,-3);if(view.StartsWith("move"))offset.x+=int.Parse(view.Substring(4))*.08f;c.transform.position=target+offset;c.transform.LookAt(target);Shot(c,"studio-"+view);}}
 public static void Field(){Empty();var result=MapTunnelBuilder.Build(Path.Combine(Root,"Input123Mine"),null,null,"Cobweb177");Check(result.built,"actual tunnel");var web=Web(new Vector3(13.15f,2.15f,11.4f),Quaternion.Euler(0,90,0));var lamp=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported164-valid/small-mine_wall_lantern.prefab"));lamp.transform.SetPositionAndRotation(new Vector3(13.17f,1.65f,10.2f),Quaternion.Euler(0,90,0));var budget=new GameObject("既存共有灯枠").AddComponent<RoomTorchBudget>();budget.Configure(new[]{lamp.GetComponent<RoomTorchInstance>()});var c=Cam();var hero=new GameObject("視点").transform;hero.position=new Vector3(12,0,11.4f);var cut=result.root.GetComponent<MapTunnels.MapTunnelCutaway>();cut.hero=hero;cut.viewCamera=c;var target=web.transform.position;foreach(var view in new[]{"normal","close","reverse","dark","absent","wall-oblique"}){web.SetActive(view!="absent");budget.TimeOverride=1;for(int i=0;i<60;i++)budget.Tick(1/30f,hero.position);if(view=="dark")lamp.GetComponent<RoomTorchInstance>().SourceLight.enabled=false;bool normal=view=="normal"||view=="dark"||view=="absent";c.transform.position=normal?hero.position+new Vector3(0,9,-6.3f):target+(view=="reverse"?new Vector3(-2,.4f,1):view=="wall-oblique"?new Vector3(-.45f,.1f,-2):new Vector3(-2,.3f,-1));c.transform.LookAt(normal?hero.position+Vector3.up*.5f:target);typeof(MapTunnels.MapTunnelCutaway).GetMethod("LateUpdate",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(cut,null);Shot(c,"mine-"+view);}File.WriteAllText(Path.Combine(Out,"field.json"),"{\"formalTunnel\":true,\"width\":2.4,\"height\":2.8,\"webPosition\":[13.15,2.15,11.4],\"webYaw\":90,\"light\":\"published mine wall lantern shared budget\",\"originalSceneChanged\":false}");}
 [Serializable]class Row{public int count,visible,meshes,materials,textures,lights;public long textureBytes,meshBytes;public double cpuMedianMs;}
 public static void Load(){Empty();var rows=new List<Row>();foreach(int count in new[]{9,225}){var root=new GameObject("共有巣"+count);int side=count==9?3:15;for(int i=0;i<count;i++)Web(new Vector3((i%side-side/2)*2,1.65f,(i/side-side/2)*2),Quaternion.identity,root.transform);var c=Cam();c.transform.position=new Vector3(0,15,-12);c.transform.LookAt(Vector3.zero);var rs=root.GetComponentsInChildren<Renderer>();var meshes=root.GetComponentsInChildren<MeshFilter>().Select(x=>x.sharedMesh).Distinct().ToArray();var mats=rs.Select(x=>x.sharedMaterial).Distinct().ToArray();var tx=mats.Select(x=>x.GetTexture("_BaseMap")).Distinct().ToArray();var planes=GeometryUtility.CalculateFrustumPlanes(c);var times=new List<double>();for(int k=0;k<7;k++){var sw=Stopwatch.StartNew();var t=Shared117Review.Image(c,640,360);sw.Stop();UnityEngine.Object.DestroyImmediate(t);if(k>1)times.Add(sw.Elapsed.TotalMilliseconds);}times.Sort();Check(meshes.Length==1&&mats.Length==1&&tx.Length==1&&root.GetComponentsInChildren<Light>().Length==0,"one mesh material texture no lights");rows.Add(new Row{count=count,visible=rs.Count(x=>GeometryUtility.TestPlanesAABB(planes,x.bounds)),meshes=1,materials=1,textures=1,lights=0,textureBytes=tx.Sum(x=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(x)),meshBytes=meshes.Sum(x=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(x)),cpuMedianMs=times[times.Count/2]});UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(c.gameObject);}File.WriteAllText(Path.Combine(Out,"load.json"),"{\"gpuMeasured\":false,\"cpuIncludesRenderTextureReadback\":true,\"rows\":["+string.Join(",",rows.Select(x=>JsonUtility.ToJson(x)))+"]}");} public static void Overlap(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=Color.gray*.2f;var light=new GameObject("中立光").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.3f;light.transform.rotation=Quaternion.Euler(35,-20,0);var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"/small-mine_cobweb.prefab");var a=(GameObject)PrefabUtility.InstantiatePrefab(prefab);var b=(GameObject)PrefabUtility.InstantiatePrefab(prefab);a.transform.position=new Vector3(0,1.65f,0);b.transform.position=new Vector3(.18f,1.75f,-.15f);b.transform.rotation=Quaternion.Euler(0,22,0);var c=new GameObject("重なり確認").AddComponent<Camera>();c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.10f,.11f,.12f);c.fieldOfView=45;foreach(var side in new[]{-1,0,1}){c.transform.position=new Vector3(side*1.1f,1.85f,-3);c.transform.LookAt(new Vector3(0,1.65f,0));var t=Shared117Review.Image(c,1280,720);File.WriteAllBytes(Path.Combine(Out,"overlap-"+side+".png"),t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}a.SetActive(false);b.transform.position=new Vector3(0,1.65f,0);b.transform.rotation=Quaternion.identity;for(int frame=0;frame<3;frame++){c.transform.position=new Vector3(frame*.08f,9.65f,-6);c.transform.LookAt(new Vector3(0,1.65f,0));var t=Shared117Review.Image(c,1280,720);File.WriteAllBytes(Path.Combine(Out,"normal-motion"+frame+".png"),t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}}
